#!/usr/bin/env python3
import sys, os, io, csv, json, gzip, re
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal, ROUND_HALF_UP
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(path):
    with open(path, 'rb') as f:
        data = f.read()
    if data[:2] == b'\x1f\x8b':
        data = gzip.decompress(data)
    t = data.decode('utf-8')
    if t.startswith('\ufeff'):
        t = t[1:]
    return t


def lines_of(text):
    return [l for l in text.replace('\r\n', '\n').replace('\r', '\n').split('\n') if l.strip() != '']


def read_csv_rows(path, **kw):
    return list(csv.reader(lines_of(read_text(path)), **kw))


def epoch(dt):  # aware dt -> int seconds
    return int(dt.timestamp() // 1) if dt.microsecond == 0 else int((dt - datetime(1970, 1, 1, tzinfo=UTC)).total_seconds() // 1)


def iso_to_epoch(s):
    s = s.strip()
    if s.endswith('Z') or s.endswith('z'):
        s = s[:-1] + '+00:00'
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=UTC)
    return epoch(dt)


def local_to_epoch(naive, tz, dst=None):
    """dst: None -> first occurrence; True/False -> choose the occurrence with/without DST."""
    a = naive.replace(tzinfo=tz, fold=0)
    b = naive.replace(tzinfo=tz, fold=1)
    if a.utcoffset() == b.utcoffset():
        return epoch(a)
    if dst is None:
        return epoch(a)
    for c in (a, b):
        if bool(c.dst()) == dst:
            return epoch(c)
    return epoch(a)


def std_offset(tz):
    offs = []
    for m in (1, 7):
        offs.append(datetime(2026, m, 1, tzinfo=tz).utcoffset())
    return min(offs)


def norm_dir(s):
    s = s.strip().upper()
    return 'IN' if s in ('IN', 'I', 'K', 'CLOCK_IN') else 'OUT'


def parse_abbr(text, tz):
    out = []
    header = None
    for row in csv.reader(lines_of(text)):
        if 'Badge' in row and 'Punch' in row:
            header = {n.strip(): i for i, n in enumerate(row)}
            continue
        if header is None:
            continue
        g = lambda n: row[header[n]].strip()
        d = datetime.strptime(g('Date'), '%m/%d/%Y')
        t = g('Time')
        m = re.fullmatch(r'(\d{1,2}):(\d\d):(\d\d)\s*([AaPp][Mm])?', t)
        h, mi, s = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if m.group(4):
            h = h % 12 + (12 if m.group(4).upper() == 'PM' else 0)
        naive = d.replace(hour=h, minute=mi, second=s)
        z = g('Zone').upper()
        dst = True if z.endswith('DT') else (False if z.endswith('ST') else None)
        out.append((g('Record'), g('Badge'), norm_dir(g('Punch')), local_to_epoch(naive, tz, dst)))
    return out


def parse_epoch(text, tz):
    out = []
    schema = 1
    for l in lines_of(text):
        o = json.loads(l)
        if not isinstance(o, dict):
            continue
        if 'schema' in o and 'heartbeat' not in o:
            schema = int(o['schema'])
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            pid, emp, dr, ts = o['punch_id'], o['employee'], o['direction'], int(o['epoch_ms']) // 1000
        else:
            pid, emp, dr = o['id'], o['emp'], o['dir']
            if 'ts_ms' in o:
                ts = int(o['ts_ms']) // 1000
            else:
                ts = int(o['ts'] // 1)
        out.append((str(pid), emp, norm_dir(dr), ts))
    return out


def parse_offset(text, tz):
    out = []
    header = None
    for row in csv.reader(lines_of(text), delimiter=';', quotechar='"'):
        if 'punch_id' in row and 'timestamp' in row:
            header = {n.strip(): i for i, n in enumerate(row)}
            continue
        if header is None:
            continue
        g = lambda n: row[header[n]].strip()
        out.append((g('punch_id'), g('employee'), norm_dir(g('event')), iso_to_epoch(g('timestamp'))))
    return out


def parse_legacy(text, tz):
    out = []
    base = std_offset(tz)
    cur = base
    for l in text.replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        if not l.strip():
            continue
        t = l[0]
        if t == 'H':
            m = re.fullmatch(r'([+-])(\d\d)(\d\d)', l[13:18].strip()) if len(l) > 13 else None
            if m:
                v = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
                cur = -v if m.group(1) == '-' else v
            else:
                cur = base
        elif t == 'D':
            pid = l[1:9]
            badge = l[9:15].strip()
            dr = l[15]
            ts = datetime.strptime(l[16:30], '%Y%m%d%H%M%S')
            e = epoch(ts.replace(tzinfo=UTC)) - int(cur.total_seconds())
            out.append((pid, 'E' + badge, 'IN' if dr == 'I' else 'OUT', e))
    return out


def parse_de(text, tz):
    out = []
    header = None
    for row in csv.reader(lines_of(text), delimiter='\t'):
        if 'Ausweis' in row and 'Buchung' in row:
            header = {n.strip(): i for i, n in enumerate(row)}
            continue
        if header is None:
            continue
        g = lambda n: row[header[n]].strip()
        naive = datetime.strptime(g('Datum') + ' ' + g('Uhrzeit'), '%d.%m.%Y %H:%M')
        z = g('Zeitzone').upper()
        dst = True if z == 'MESZ' else (False if z == 'MEZ' else None)
        out.append((g('Nr'), g('Ausweis'), norm_dir(g('Buchung')), local_to_epoch(naive, tz, dst)))
    return out


def parse_localcsv(text, tz):
    out = []
    header = None
    for row in csv.reader(lines_of(text)):
        if 'employee_id' in row and 'local_time' in row:
            header = {n.strip(): i for i, n in enumerate(row)}
            continue
        if header is None:
            continue
        g = lambda n: row[header[n]].strip()
        naive = datetime.strptime(g('local_time'), '%Y-%m-%d %H:%M:%S')
        out.append((g('punch_ref'), g('employee_id'), norm_dir(g('direction')), local_to_epoch(naive, tz)))
    return out


def parse_localjsonl(text, tz):
    out = []
    for l in lines_of(text):
        o = json.loads(l)
        p = o.get('punch') if isinstance(o, dict) else None
        if not p:
            continue
        naive = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        out.append((str(p['id']), p['badge'], norm_dir(p['type']), local_to_epoch(naive, tz)))
    return out


PARSERS = {'abbr-csv': parse_abbr, 'epoch-jsonl': parse_epoch, 'offset-csv': parse_offset,
           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_localcsv,
           'local-jsonl': parse_localjsonl}


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = iso_to_epoch(period['corrections_cutoff'])

    sites = {}
    for r in csv.DictReader(lines_of(read_text(os.path.join(inp, 'sites.csv')))):
        sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    employees = {}
    for r in csv.DictReader(lines_of(read_text(os.path.join(inp, 'employees.csv')))):
        employees[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    for r in csv.DictReader(lines_of(read_text(os.path.join(inp, 'rates.csv')))):
        rates.setdefault(r['employee_id'].strip(), []).append(
            (date.fromisoformat(r['effective_from'].strip()), Decimal(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect
    punches = {}   # (site,id) -> [emp, dir, ts]
    ever = set()
    for site, (tz, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        files = []
        for root, _, fs in os.walk(d):
            for f in fs:
                files.append(os.path.join(root, f))
        for f in sorted(files):
            for pid, emp, dr, ts in PARSERS[fmt](read_text(f), tz):
                k = (site, pid)
                if k not in punches:
                    punches[k] = [emp, dr, ts]
                ever.add(k)

    # 2. corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for root, _, fs in os.walk(cdir):
            for f in fs:
                rows = read_csv_rows(os.path.join(root, f))
                if not rows:
                    continue
                h = [x.strip() for x in rows[0]]
                for row in rows[1:]:
                    c = {h[i]: row[i].strip() for i in range(min(len(h), len(row)))}
                    if 'correction_id' not in c:
                        continue
                    c['_t'] = iso_to_epoch(c['issued_at'])
                    corr.append(c)
    corr.sort(key=lambda c: (c['_t'], c['correction_id']))
    applied = 0
    voided = set()
    for c in corr:
        if c['_t'] > cutoff:
            continue
        k = (c.get('site', ''), c.get('punch_id', ''))
        a = c.get('action', '').lower()
        if a == 'void':
            if k in punches and k not in voided:
                voided.add(k)
                del punches[k]
                applied += 1
        elif a == 'set':
            if k in punches and k not in voided:
                punches[k][2] = iso_to_epoch(c['time'])
                applied += 1
        elif a == 'add':
            if k not in ever:
                punches[k] = [c['employee'], norm_dir(c['type']), iso_to_epoch(c['time'])]
                ever.add(k)
                applied += 1

    # group per employee
    per = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in employees:
            per.setdefault(emp, []).append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(ts, tz):
        off = int(datetime.fromtimestamp(ts, tz).utcoffset().total_seconds())
        r = (ts + off) % 360
        return ts - r if r < 180 else ts + (360 - r)

    exc = {'open_shifts': 0, 'orphan_outs': 0, 'duplicates_dropped': 0, 'corrections_applied': applied}
    res = {e: {'shifts': 0, 'paid_minutes': 0, 'overtime_minutes': 0, 'night_minutes': 0, 'gross': Decimal(0)}
           for e in employees}

    def workday(rts, hz):
        return datetime.fromtimestamp(rts, hz).date()

    def in_period(d):
        return pstart <= d <= pend

    def night_minutes(a, b, tz):
        d0 = datetime.fromtimestamp(a, tz).date() - timedelta(days=1)
        d1 = datetime.fromtimestamp(b, tz).date()
        tot = 0
        d = d0
        while d <= d1:
            s = local_to_epoch(datetime(d.year, d.month, d.day, 22), tz)
            n = d + timedelta(days=1)
            e = local_to_epoch(datetime(n.year, n.month, n.day, 6), tz)
            lo, hi = max(a, s), min(b, e)
            if hi > lo:
                tot += (hi - lo) // 60
            d += timedelta(days=1)
        return tot

    for emp, plist in per.items():
        hz = sites[employees[emp]][0]
        plist.sort()
        kept = []
        for ts, _, site, pid, dr in plist:
            tz = sites[site][0]
            rts = rnd(ts, tz)
            if kept and kept[-1][4] == dr and ts - kept[-1][0] <= 300:
                if in_period(workday(rts, hz)):
                    exc['duplicates_dropped'] += 1
                continue
            kept.append((ts, site, pid, rts, dr))
        shifts = []  # (rin, rout, site)
        i = 0
        n = len(kept)
        while i < n:
            k = kept[i]
            if k[4] == 'IN':
                if i + 1 < n and kept[i + 1][4] == 'OUT' and kept[i + 1][3] - k[3] <= 16 * 3600:
                    shifts.append((k[3], kept[i + 1][3], k[1]))
                    i += 2
                    continue
                if in_period(workday(k[3], hz)):
                    exc['open_shifts'] += 1
            else:
                if in_period(workday(k[3], hz)):
                    exc['orphan_outs'] += 1
            i += 1
        shifts.sort(key=lambda s: s[0])
        days = {}
        weeks = {}
        r = res[emp]
        exact = Fraction_sum = Decimal(0)
        from fractions import Fraction
        total = Fraction(0)
        for rin, rout, site in shifts:
            wd = workday(rin, hz)
            if not in_period(wd):
                continue
            tz = sites[site][0]
            worked = max(0, (rout - rin) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(rin, rout, tz), paid)
            before = days.get(wd, 0)
            days[wd] = before + paid
            dot = max(0, before + paid - max(before, 480))
            nd = paid - dot
            wk = wd - timedelta(days=wd.weekday())
            wb = weeks.get(wk, 0)
            weeks[wk] = wb + nd
            wot = max(0, wb + nd - max(wb, 2400))
            ot = dot + wot
            reg = paid - ot
            rate = None
            for ef, rt in rates.get(emp, []):
                if ef <= wd:
                    rate = rt
            if rate is None:
                rate = Decimal(0)
            rate = Fraction(rate)
            total += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            r['shifts'] += 1
            r['paid_minutes'] += paid
            r['overtime_minutes'] += ot
            r['night_minutes'] += night
        cents = total * 100
        r['gross'] = int(cents + Fraction(1, 2) // 1) if False else (cents.numerator * 2 + cents.denominator) // (2 * cents.denominator)

    emps_out = {}
    tot = {'shifts': 0, 'paid_minutes': 0, 'overtime_minutes': 0, 'night_minutes': 0}
    tg = 0
    for e in sorted(employees):
        r = res[e]
        g = r['gross'] if isinstance(r['gross'], int) else 0
        emps_out[e] = {k: r[k] for k in tot}
        emps_out[e]['gross'] = '%d.%02d' % (g // 100, g % 100)
        for k in tot:
            tot[k] += r[k]
        tg += g
    tot['gross'] = '%d.%02d' % (tg // 100, tg % 100)
    out = {'period': {'start': period['start'], 'end': period['end']}, 'employees': emps_out,
           'exceptions': exc, 'totals': tot}
    with open(outp, 'w') as f:
        json.dump(out, f, indent=1)


main()
